-- 020_crop_fertilizer_note.sql
-- เพิ่มช่อง "หมายเหตุ" การใส่ปุ๋ย (แสดงต่อจากขั้นที่ 6 ในฟอร์ม)
-- ที่มา: โฟลเดอร์ E:/DOA_Soil/คำแนะนำ ไฟล์ '5. ไม้ผล-...ใหม่.xlsx' (เริ่มไม้ผลก่อน)

alter table public.crops add column if not exists fertilizer_note text;
alter table public.crops add column if not exists fertilizer_note_source text;

update public.crops set fertilizer_note = E'1. ระยะที่ยังไม่ให้ผลผลิตใส่ปุ๋ยอินทรีย์ อัตรา 15-30 กิโลกรัมต่อต้น ร่วมกับปุ๋ยเคมี 15-15-15 อัตรา 1,400 กรัมต่อต้นต่อปี ร่วมกับปุ๋ยยูเรีย (46-0-0) อัตรา 220 กรัมต่อต้นต่อปี โดยแบ่งใส่ปุ๋ย 2 ครั้งต่อปี โดยหว่านปุ๋ยรอบทรงพุ่ม แล้วพรวนดินกลบ แล้วรดน้ำตาม
2. ปุ๋ยโพแทสเซียม สามารถใช้ปุ๋ย 0-0-50 หรือ 0-0-60 ซึ่งมีราคาถูกกว่า แต่การใส่ปุ๋ย 0-0-50 ทุเรียนจะได้รับธาตุกำมะถันเพิ่มเติม สามารถช่วยเพิ่มกลิ่นและรสชาติของทุเรียนให้ดีขึ้น', fertilizer_note_source = E'ดัดแปลงจากกรมวิชาการเกษตร (2566)' where id = 'e3f8b7b3-7526-4dad-894b-aa073b7f9e37';  -- ทุเรียน
update public.crops set fertilizer_note = E'ระยะยังไม่ให้ผลผลิต(อายุ 1-5 ปี) หว่านปุ๋ยอินทรีย์อัตรา 15-30 กิโลกรัมต่อต้น ร่วมกับปุ๋ย 20-10-10 อัตรา 0.5-1.0 กิโลกรัม/ต้น/ปี โดยหว่านรอบทรงพุ่ม แล้วพรวนดินกลบ และรดน้ำตาม โดยปุ๋ยเคมีแบ่งใส่ปุ๋ย 2 ครั้งต่อปี', fertilizer_note_source = E'ดัดแปลงจากกรมวิชาการเกษตร (2566)' where id = '8c453172-acf1-47e9-9234-f47678c7365e';  -- มังคุด
update public.crops set fertilizer_note = E'ระยะที่ยังไม่ให้ผลผลิตใส่ปุ๋ยอินทรีย์ อัตรา 15-30 กิโลกรัมต่อต้นต่อปี ร่วมกับใส่ปุ๋ยเคมี 15-15-15 อัตรา 400 กรัมต่อต้น โดยแบ่งใส่ปุ๋ยเป็น 2 ครั้ง
